import React from 'react';

const VersionList = ({ data }) => {
  if (!data.length) return <p className="errorHandling">No results found.</p>;

  return (
    <ol className="versionListClassSection">
      {data.map((item, idx) => (
        <li key={idx} className="versionListClassSection-item">
          <div>
            <strong>{item.versionProductName}</strong> - {item.versionNumber}
          </div>
        </li>
      ))}
    </ol>
  );
};

export default VersionList;
